use std::thread::{self, JoinHandle};

fn workers(data: Arc<[u8]>) -> Vec<JoinHandle<usize>> {
    (0..2).map(|_| {
        let data = Arc::clone(&data);
        thread::spawn(move || data.len())
    }).collect()
}

