fn parse_values(values: &[String]) -> (Vec<u64>, usize) {
    let mut skipped = 0;
    let parsed = values.iter()
        .map(|value| value.parse::<u64>())
        .map(|result| {
            if result.is_err() { skipped += 1; }
            result
        })
        .filter_map(Result::ok)
        .collect();
    (parsed, skipped)
}

